data.code:
# REST: Simple and readable
POST /api/users
{
  "name": "Alice",
  "email": "alice@example.com"
}

# gRPC: Binary and strongly typed
message CreateUserRequest {
  string name = 1;
  string email = 2;
}
service UserService {
  rpc CreateUser(CreateUserRequest) returns (User);
}

# GraphQL: Client-driven query
mutation {
  createUser(input: { name: "Alice", email: "alice@example.com" }) {
    id
    name
    email
  }
}

data.definition:
flowchart TD
    A[Need service communication] --> B{Internal or external?}
    B -->|External| C[Use REST]
    B -->|Internal| D{Performance critical?}
    D -->|Yes| E[Use gRPC]
    D -->|No| F{Complex data needs?}
    F -->|Yes| G[Use GraphQL]
    F -->|No| C
